solution.mechanics.zig:
const m = @import("model.zig");
fn remove_enemy(s: *m.Arena, i: usize) void {
    var j = i + 1;
    while (j < s.count) : (j += 1) s.enemies[j - 1] = s.enemies[j];
    s.count -= 1;
}
pub fn arena_step(s: *m.Arena, action: u8) void {
    if (s.won or s.health <= 0) return;
    s.fired = false;
    s.hit = false;
    if (action == 'a' and s.player > 0) s.player -= 1;
    if (action == 'd' and s.player < m.width - 1) s.player += 1;
    if (s.cooldown > 0) s.cooldown -= 1;
    if (action == 'f' and s.cooldown == 0) {
        s.fired = true;
        s.cooldown = 3;
        var target: ?usize = null;
        for (s.enemies[0..s.count], 0..) |enemy, i| {
            if (enemy.x == s.player and (target == null or enemy.y > s.enemies[target.?].y)) target = i;
        }
        if (target) |i| {
            remove_enemy(s, i);
            s.score += 1;
            s.hit = true;
        }
    }
    var i: usize = 0;
    while (i < s.count) {
        s.enemies[i].y += 1;
        if (s.enemies[i].y >= m.height - 1) {
            remove_enemy(s, i);
            if (s.health > 0) s.health -= 1;
        } else i += 1;
    }
    s.tick += 1;
    if (s.health > 0 and s.score < 3 and s.tick % 4 == 0 and s.count < m.max_enemies) {
        const columns = [_]i32{ 4, 2, 6 };
        s.enemies[s.count] = .{ .x = columns[s.waves % 3], .y = 0 };
        s.count += 1;
        s.waves += 1;
    }
    s.won = s.health > 0 and s.score >= 3;
}

