const std = @import("std");
const m = @import("model.zig");
const learner = @import("mechanics.zig");
extern "c" fn printf(format: [*:0]const u8, ...) c_int;
extern "c" fn getchar() c_int;
extern "c" fn putchar(c_int) c_int;
extern "c" fn puts([*:0]const u8) c_int;
extern "c" fn exit(c_int) noreturn;
fn truth(b: bool) [*:0]const u8 {
    return if (b) "true" else "false";
}
fn frame(s: m.Arena, action: u8) void {
    _ = printf("{\"type\":\"frame\",\"tick\":%u,\"action\":\"%c\",\"player\":%d,\"health\":%d,\"cooldown\":%u,\"waves\":%u,\"score\":%u,\"fired\":%s,\"hit\":%s,\"won\":%s,\"enemies\":[", @as(c_uint, s.tick), @as(c_int, action), @as(c_int, s.player), @as(c_int, s.health), @as(c_uint, s.cooldown), @as(c_uint, s.waves), @as(c_uint, s.score), truth(s.fired), truth(s.hit), truth(s.won));
    for (s.enemies[0..s.count], 0..) |enemy, i| {
        _ = printf("%s{\"x\":%d,\"y\":%d}", @as([*:0]const u8, if (i == 0) "" else ","), @as(c_int, enemy.x), @as(c_int, enemy.y));
    }
    _ = puts("]}");
}
fn draw(s: m.Arena) void {
    _ = puts("\nWave Arena: a/d move, f fires, . waits; Enter after each action; q quits.");
    for (0..m.height) |y| {
        _ = putchar('|');
        for (0..m.width) |x| {
            var cell: u8 = '.';
            for (s.enemies[0..s.count]) |enemy| {
                if (enemy.x == x and enemy.y == y) cell = 'V';
            }
            if (y == m.height - 1 and s.player == x) cell = 'A';
            _ = putchar(@as(c_int, cell));
        }
        _ = puts("|");
    }
    _ = printf("Health %d | score %u/3 | cooldown %u | waves %u | tick %u | %s\n", @as(c_int, s.health), @as(c_uint, s.score), @as(c_uint, s.cooldown), @as(c_uint, s.waves), @as(c_uint, s.tick), @as([*:0]const u8, if (s.won) "YOU WIN" else if (s.health <= 0) "GAME OVER" else if (s.hit) "Enemy hit" else if (s.fired) "Shot fired" else "Ready for input"));
}
pub fn main(init: std.process.Init) !void {
    const args = try init.minimal.args.toSlice(init.arena.allocator());
    var s = m.arena_initial();
    if (args.len == 3 and std.mem.eql(u8, args[1], "--replay")) {
        _ = puts("{\"type\":\"header\",\"project\":\"wave-arena\",\"version\":1,\"language\":\"zig\"}");
        frame(s, '.');
        for (args[2]) |action| {
            if (s.won or s.health <= 0) break;
            if (std.mem.indexOfScalar(u8, "adf.", action) == null) {
                _ = puts("Replay actions must use a/d/f/.");
                exit(2);
            }
            learner.arena_step(&s, action);
            frame(s, action);
        }
        return;
    }
    if (args.len != 1) {
        _ = puts("Usage: game [--replay ACTIONS]");
        exit(2);
    }
    draw(s);
    while (!s.won and s.health > 0) {
        const input = getchar();
        if (input < 0 or input == 'q') break;
        if (input > 255) continue;
        const action: u8 = @intCast(input);
        if (std.mem.indexOfScalar(u8, "adf.", action) == null) continue;
        learner.arena_step(&s, action);
        draw(s);
    }
}

files.tests.zig:
const std = @import("std");
const t = std.testing;
const m = @import("model.zig");
const learner = @import("mechanics.zig");
test "first shot starts cooldown" {
    var s = m.arena_initial();
    learner.arena_step(&s, 'f');
    try t.expect(s.fired and s.cooldown == 3);
}
test "consecutive shots wait exactly three ticks" {
    var s = m.arena_initial();
    learner.arena_step(&s, 'f');
    learner.arena_step(&s, 'f');
    try t.expect(!s.fired and s.cooldown == 2);
    learner.arena_step(&s, 'f');
    try t.expect(!s.fired and s.cooldown == 1);
    learner.arena_step(&s, 'f');
    try t.expect(s.fired and s.cooldown == 3);
}
test "wave spawns at tick four without moving early" {
    var s = m.arena_initial();
    for (0..3) |_| learner.arena_step(&s, '.');
    try t.expect(s.count == 0);
    learner.arena_step(&s, '.');
    try t.expect(s.count == 1 and s.enemies[0].x == 4 and s.enemies[0].y == 0 and s.waves == 1);
}
test "surviving enemies advance once per tick" {
    var s = m.arena_initial();
    for (0..5) |_| learner.arena_step(&s, '.');
    try t.expect(s.enemies[0].y == 1);
}
test "escaping enemy damages health and next wave changes column" {
    var s = m.arena_initial();
    for (0..8) |_| learner.arena_step(&s, '.');
    try t.expect(s.health == 2 and s.count == 1 and s.enemies[0].x == 2 and s.enemies[0].y == 0);
}
test "shot selects nearest enemy and advances survivors" {
    var s = m.arena_initial();
    s.count = 2;
    s.enemies[0] = .{ .x = 4, .y = 1 };
    s.enemies[1] = .{ .x = 4, .y = 3 };
    learner.arena_step(&s, 'f');
    try t.expect(s.score == 1 and s.hit and s.count == 1 and s.enemies[0].y == 2 and s.health == 3);
}
test "movement is clamped to arena columns" {
    var s = m.arena_initial();
    for (0..12) |_| learner.arena_step(&s, 'a');
    try t.expect(s.player == 0);
}
test "native arena has a playable winning route" {
    var s = m.arena_initial();
    for ("....faa.fddddf") |a| learner.arena_step(&s, a);
    try t.expect(s.won and s.score == 3 and s.health == 3);
}
test "won state does not advance" {
    var s = m.arena_initial();
    for ("....faa.fddddf") |a| learner.arena_step(&s, a);
    const tick = s.tick;
    learner.arena_step(&s, 'a');
    try t.expect(s.won and s.tick == tick);
}
test "unopposed enemies produce a real loss" {
    var s = m.arena_initial();
    for (0..16) |_| learner.arena_step(&s, '.');
    try t.expect(s.health == 0 and !s.won);
    const tick = s.tick;
    learner.arena_step(&s, 'f');
    try t.expect(s.tick == tick and !s.fired);
}
